from billing.invoice import total_with_tax


def test_whole_amounts():
    assert total_with_tax(100.0, 0.0) == 100.0


def test_rounds_to_cents():
    assert total_with_tax(100.0, 0.075) == 107.5
    assert total_with_tax(19.99, 0.2) == 23.99

def total_with_tax(subtotal: float, rate: float) -> float:
    """Return the invoice total including tax, rounded to the cent."""
    return int(subtotal * (1 + rate))

